-- =============================================================================
-- 0012 — Ficha técnica: interruptores, categorías y precarga desde la fuente
-- -----------------------------------------------------------------------------
-- - tienda.mostrar_ficha: "Mostrar la ficha técnica en el sitio" (sí por
--   defecto). Apagado, el sitio no muestra "Ver ficha técnica".
-- - tienda.ficha_ocultas: categorías que la tienda apagó. Las categorías son
--   fijas (claves de abajo); "otras" son las filas que agrega la tienda.
-- - fichas.especificaciones: cada fila puede llevar "clave" (una categoría
--   fija). Sin clave, es una fila de la tienda. validar_ficha revisa el
--   formato (el adaptador demo repite las mismas reglas).
-- - Precarga de las fichas de los 42 modelos SOLO con lo que traen los
--   archivos de Jared (HTML del inventario para el iPhone 7 al 16 Pro Max e
--   info_complementaria.md para el resto). Lo que no traen queda vacío (la
--   batería en todos; ver la sección 17 de DOCUMENTACION.md). Solo se cargan
--   en fichas sin filas: lo que ya cargó la tienda no se toca.
--   assets/js/datos/semilla.js (FICHAS) tiene lo mismo.
-- =============================================================================

alter table public.tienda
  add column mostrar_ficha boolean not null default true,
  add column ficha_ocultas text[] not null default '{}'
    check (ficha_ocultas <@ array['lanzamiento', 'procesador', 'pantalla', 'camaras_traseras', 'camara_frontal',
                                   'bateria', 'versiones', 'materiales', 'puertos', 'dimensiones', 'otras']);

create or replace function public.validar_ficha()
returns trigger language plpgsql set search_path = public as $$
declare
  fila jsonb;
  claves text[] := '{}';
begin
  for fila in select * from jsonb_array_elements(new.especificaciones) loop
    if jsonb_typeof(fila) <> 'object'
       or jsonb_typeof(fila -> 'etiqueta') is distinct from 'string'
       or jsonb_typeof(fila -> 'valor') is distinct from 'string'
       or length(fila ->> 'etiqueta') > 60 or length(fila ->> 'valor') > 600
       or (fila ? 'clave' and jsonb_typeof(fila -> 'clave') <> 'null' and (
             jsonb_typeof(fila -> 'clave') <> 'string'
             or not (fila ->> 'clave' = any (array['lanzamiento', 'procesador', 'pantalla', 'camaras_traseras', 'camara_frontal',
                                                   'bateria', 'versiones', 'materiales', 'puertos', 'dimensiones']))
             or fila ->> 'clave' = any (claves))) then
      raise exception 'Alguna fila de la ficha técnica no tiene el formato correcto.' using errcode = '23514';
    end if;
    if fila ? 'clave' and jsonb_typeof(fila -> 'clave') = 'string' then claves := claves || (fila ->> 'clave'); end if;
  end loop;
  return new;
end $$;

create trigger fichas_validar before insert or update of especificaciones on public.fichas
  for each row execute function public.validar_ficha();

-- Por si algún modelo de la lista no tuviera su fila (la crea modelos_ficha).
insert into public.fichas (modelo_id)
select id from public.modelos on conflict do nothing;

update public.fichas f
set especificaciones = v.filas
